CREATE TABLE remessas (id INTEGER PRIMARY KEY AUTOINCREMENT, chave TEXT NOT NULL UNIQUE, cenario TEXT NOT NULL, ug TEXT NOT NULL, competencia INTEGER NOT NULL, estado TEXT NOT NULL DEFAULT 'ABERTO' CHECK(estado='ABERTO'), abertura TEXT NOT NULL, atividade TEXT NOT NULL, UNIQUE(id,cenario,ug));
CREATE UNIQUE INDEX remessa_aberta_unica ON remessas(cenario,ug,competencia) WHERE estado='ABERTO';
CREATE TABLE lotes (numero INTEGER PRIMARY KEY AUTOINCREMENT, remessa_id INTEGER NOT NULL, cenario TEXT NOT NULL, ug TEXT NOT NULL, ordem INTEGER NOT NULL CHECK(ordem>0), assunto TEXT NOT NULL CHECK(assunto='CADASTRO_CONTRIBUINTE'), payload BLOB NOT NULL, hash TEXT NOT NULL, registros INTEGER NOT NULL CHECK(registros>0), recebimento TEXT NOT NULL, UNIQUE(remessa_id,ordem), UNIQUE(numero,remessa_id,cenario,ug), FOREIGN KEY(remessa_id,cenario,ug) REFERENCES remessas(id,cenario,ug));
CREATE TABLE remessa_eventos (id INTEGER PRIMARY KEY AUTOINCREMENT, remessa_id INTEGER NOT NULL, cenario TEXT NOT NULL, ug TEXT NOT NULL, lote_id INTEGER, tipo TEXT NOT NULL, instante TEXT NOT NULL, FOREIGN KEY(remessa_id,cenario,ug) REFERENCES remessas(id,cenario,ug), FOREIGN KEY(lote_id,remessa_id,cenario,ug) REFERENCES lotes(numero,remessa_id,cenario,ug));
PRAGMA user_version=2;
